import { base64ToBytes } from '../util/base64';

// Real JPEG 2000 codestreams -- the exact bytes a PDF /JPXDecode filter carries -- produced by OpenJPEG 2.5.4 (opj_compress) from deterministic source images, by scripts/generate-jpeg2000-fixtures.mjs. Embedded as base64 so the suite needs no filesystem access.
//
// For every `lossless: true` fixture, `expected` is the SOURCE image the encoder was handed, not any decoder's output: the generator first proves the configuration round-trips byte-identically through OpenJPEG's own decoder, which makes the source an exact oracle that neither this package nor OpenJPEG produced. A decoder reproducing it has reproduced the original integers.
//
// For a `lossless: false` fixture the transform is the irreversible 9-7 one, which has no exact answer to reproduce; `expected` is opj_decompress's own output and the test asserts a tight per-sample tolerance against it rather than equality. See the generator script's header for the full statement of what each kind of fixture does and does not establish.
//
// `expected` decodes to one sample per component in planar order (every sample of component 0, then component 1, ...), one byte per sample for an 8-bit fixture and one little-endian 16-bit word per sample for a deeper one.

export interface Jpeg2000Fixture {
  readonly name: string;
  readonly description: string;
  readonly width: number;
  readonly height: number;
  readonly componentCount: number;
  readonly bitDepth: number;
  // Whether `expected` is the encoder's own input (a reversible configuration) rather than OpenJPEG's decode of a lossy one.
  readonly lossless: boolean;
  // Set for a fixture recorded only so a scope refusal can be tested against real encoder output; its `expected` field is empty because there is nothing this decoder is meant to produce for it.
  readonly undecodable: boolean;
  readonly codestream: string;
  readonly expected: string;
}

export function jpeg2000FixtureBytes(encoded: string): Uint8Array<ArrayBuffer> {
  return base64ToBytes(encoded);
}

// Decodes a fixture's `expected` field into one array per component, matching what decodeJpeg2000 returns.
export function jpeg2000FixtureSamples(fixture: Jpeg2000Fixture): number[][] {
  const bytes = base64ToBytes(fixture.expected);
  const wide = fixture.bitDepth > 8;
  const perComponent = fixture.width * fixture.height;
  const planes: number[][] = [];
  for (let c = 0; c < fixture.componentCount; c++) {
    const plane: number[] = [];
    for (let i = 0; i < perComponent; i++) {
      const at = (c * perComponent + i) * (wide ? 2 : 1);
      plane.push(wide ? (bytes[at] ?? 0) | ((bytes[at + 1] ?? 0) << 8) : (bytes[at] ?? 0));
    }
    planes.push(plane);
  }
  return planes;
}

